Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='toolguard', at=datetime(2026, 9, 1, 0, 0, 0), actor='assistant', title="The fence is scripts/tool-guard.sh, a PreToolUse hook that permits the agent's verbs and ToolSearch and refuses the rest", body='*The fence is `scripts/tool-guard.sh`*: a PreToolUse hook, matcher `.*`, that permits `mcp__suzatary__*` plus `ToolSearch` and exits 2 on everything else, INCLUDING tools that do not exist yet. ⚠️ `permissions.allow` is NOT an exclusive allowlist (measured 2026-09-01: under `dontAsk` with `allow: ["mcp__suzatary__*"]` an agent called `Monitor`, shell not named `Bash`, and got uid 1000). A bare `deny` does remove a tool, but a blocklist of names loses to the next release. ⚠️ Never deny `ToolSearch`: the verbs are DEFERRED tools loaded through it; denying it leaves the agent silently toolless, not safe.', rationale='Measured 2026-09-01: under dontAsk with allow ["mcp__suzatary__*"] an agent called Monitor, a shell not named Bash, and got uid 1000.', supersedes=()))